use super::*;

/// Point `current` at the staged binary, remembering what it displaced as `previous`.
pub fn swap(device: &Device, name: &str, sha: &str) -> Result<(), String> {
    let script = format!(
        "r=$HOME/{REMOTE_ROOT}; \
         if [ -L \"$r/{name}.current\" ]; then cp -P \"$r/{name}.current\" \"$r/{name}.previous.tmp\" && mv \"$r/{name}.previous.tmp\" \"$r/{name}.previous\"; fi; \
         ln -sfn \"$r/bin/{name}-{sha}\" \"$r/{name}.current.tmp\" && mv -T \"$r/{name}.current.tmp\" \"$r/{name}.current\" && echo OK"
    );
    ssh(device, &script).map(|_| ())
}
